def _compositor_refresh(self) -> None:
    """Perform a compositor refresh."""

    app = self.app

    if app.is_inline:
        if self is app.screen:
            inline_height = app._get_inline_height()
            clear = (
                app._previous_inline_height is not None
                and inline_height < app._previous_inline_height
            )
            app._display(
                self,
                self._compositor.render_inline(
                    app.size.with_height(inline_height),
                    screen_stack=app._background_screens,
                    clear=clear,
                ),
            )
            app._previous_inline_height = inline_height
            self._dirty_widgets.clear()
            self._compositor._dirty_regions.clear()
        elif (
            self in self.app._background_screens and self._compositor._dirty_regions
        ):
            app.screen.refresh(*self._compositor._dirty_regions)
            self._compositor._dirty_regions.clear()
            self._dirty_widgets.clear()

    else:
        if self is app.screen:
            # Top screen
            update = self._compositor.render_update(
                screen_stack=app._background_screens
            )
            app._display(self, update)
            self._dirty_widgets.clear()
        elif (
            self in self.app._background_screens and self._compositor._dirty_regions
        ):
            self._set_dirty(*self._compositor._dirty_regions)
            app.screen.refresh(*self._compositor._dirty_regions)
            self._repaint_required = True
            self._compositor._dirty_regions.clear()
            self._dirty_widgets.clear()
    app._update_mouse_over(self)

def _on_timer_update(self) -> None:
    """Called by the _update_timer."""
    self._update_timer.pause()
    if self.is_current and not self.app._batch_count:
        if self._layout_required:
            self._refresh_layout()
            self._layout_required = False
            self._scroll_required = False
            self._dirty_widgets.clear()
        elif self._scroll_required:
            self._refresh_layout(scroll=True)
            self._scroll_required = False

        if self._repaint_required:
            self._dirty_widgets.clear()
            self._dirty_widgets.add(self)
            self._repaint_required = False

def watch_scroll_x(self, old_value: float, new_value: float) -> None:
    self.horizontal_scrollbar.position = round(new_value)
    if round(old_value) != round(new_value):
        self._refresh_scroll()

def watch_scroll_y(self, old_value: float, new_value: float) -> None:
    self.vertical_scrollbar.position = round(new_value)
    if round(old_value) != round(new_value):
        self._refresh_scroll()

def validate_scroll_x(self, value: float) -> float:
    return clamp(value, 0, self.max_scroll_x)

def validate_scroll_target_x(self, value: float) -> float:
    return clamp(value, 0, self.max_scroll_x)

def validate_scroll_y(self, value: float) -> float:
    return clamp(value, 0, self.max_scroll_y)

def validate_scroll_target_y(self, value: float) -> float:
    return clamp(value, 0, self.max_scroll_y)

@property
def max_scroll_x(self) -> int:
    """The maximum value of `scroll_x`."""
    return max(
        0,
        self.virtual_size.width
        - (self.container_size.width - self.scrollbar_size_vertical),
    )

def _display(self, screen: Screen, renderable: RenderableType | None) -> None:
    """Display a renderable within a sync.

    Args:
        screen: Screen instance
        renderable: A Rich renderable.
    """

    try:
        if renderable is None:
            return

        if (
            self._running
            and not self._closed
            and not self.is_headless
            and self._driver is not None
        ):
            console = self.console
            self._begin_update()
            try:
                try:
                    if isinstance(renderable, CompositorUpdate):
                        cursor_position = self.screen.outer_size.clamp_offset(
                            self.cursor_position
                        )
                        if self._driver.is_inline:
                            terminal_sequence = Control.move(
                                *(-self._previous_cursor_position)
                            ).segment.text
                            terminal_sequence += renderable.render_segments(console)
                            terminal_sequence += Control.move(
                                *cursor_position
                            ).segment.text
                        else:
                            terminal_sequence = renderable.render_segments(console)
                            terminal_sequence += Control.move_to(
                                *cursor_position
                            ).segment.text
                        self._previous_cursor_position = cursor_position
                    else:
                        segments = console.render(renderable)
                        terminal_sequence = console._render_buffer(segments)
                except Exception as error:
                    self._handle_exception(error)
                else:
                    if WINDOWS:
                        # Combat a problem with Python on Windows.
                        #
                        # https://github.com/Textualize/textual/issues/2548
                        # https://github.com/python/cpython/issues/82052
                        CHUNK_SIZE = 8192
                        write = self._driver.write
                        for chunk in (
                            terminal_sequence[offset : offset + CHUNK_SIZE]
                            for offset in range(
                                0, len(terminal_sequence), CHUNK_SIZE
                            )
                        ):
                            write(chunk)
                    else:
                        self._driver.write(terminal_sequence)
            finally:
                self._end_update()

            self._driver.flush()

    finally:
        self.post_display_hook()

def post_display_hook(self) -> None:
    """Called immediately after a display is done. Used in tests."""

def get_widget_at(self, x: int, y: int) -> tuple[Widget, Region]:
    """Get the widget under the given coordinates.

    if top:
        delta_y = top_ - window_top

    elif not (
        (window_bottom > top_ >= window_top)
        and (window_bottom > bottom >= window_top)
    ):
        # The window needs to scroll on the Y axis to bring region in to view
        delta_y = min(
            top_ - window_top,
            top_ - (window_bottom - region.height),
            key=abs,
        )
    return Offset(delta_x, delta_y)

def __bool__(self) -> bool:
    """A Region is considered False when it has no area."""
    _, _, width, height = self
    return width * height > 0

@property
def column_span(self) -> tuple[int, int]:
    """A pair of integers for the start and end columns (x coordinates) in this region.

    The end value is *exclusive*.
    """
    return (self.x, self.x + self.width)

@property
def line_span(self) -> tuple[int, int]:
    """A pair of integers for the start and end lines (y coordinates) in this region.

    The end value is *exclusive*.
    """
    return (self.y, self.y + self.height)

@property
def right(self) -> int:
    """Maximum X value (non inclusive)."""
    return self.x + self.width

@property
def bottom(self) -> int:
    """Maximum Y value (non inclusive)."""
    return self.y + self.height

@property
def area(self) -> int:
    """The area under the region."""
    return self.width * self.height

@property
def offset(self) -> Offset:
    """The top left corner of the region.

    Returns:
        An offset.
    """
    return Offset(*self[:2])

@property
def center(self) -> tuple[float, float]:
    """The center of the region.

    Note, that this does *not* return an `Offset`, because the center may not be an integer coordinate.

    Returns:
        Tuple of floats.
    """
    x, y, width, height = self
    return (x + width / 2.0, y + height / 2.0)

@property
def bottom_left(self) -> Offset:
    """Bottom left offset of the region.

    Returns:
        An offset.
    """
    x, y, _width, height = self
    return Offset(x, y + height)

@property
def top_right(self) -> Offset:
    """Top right offset of the region.

    Returns:
        An offset.
    """
    x, y, width, _height = self
    return Offset(x + width, y)

@property
def bottom_right(self) -> Offset:
    """Bottom right offset of the region.

    Returns:
        An offset.
    """
    x, y, width, height = self
    return Offset(x + width, y + height)

@property
def size(self) -> Size:
    """Get the size of the region."""
    return Size(*self[2:])

@property
def corners(self) -> tuple[int, int, int, int]:
    """The top left and bottom right coordinates as a tuple of four integers."""
    x, y, width, height = self
    return x, y, x + width, y + height

@property
def column_range(self) -> range:
    """A range object for X coordinates."""
    return range(self.x, self.x + self.width)

@property
def line_range(self) -> range:
    """A range object for Y coordinates."""
    return range(self.y, self.y + self.height)

@property
def reset_offset(self) -> Region:
    """An region of the same size at (0, 0).

    Returns:
        A region at the origin.
    """

from textual._compositor import Compositor
from textual.geometry import Region


def test_regions_to_ranges_no_regions():
    assert list(Compositor._regions_to_spans([])) == []


def test_regions_to_ranges_single_region():
    regions = [Region(0, 0, 3, 2)]
    assert list(Compositor._regions_to_spans(regions)) == [
        (0, 0, 3),
        (1, 0, 3),
    ]


def test_regions_to_ranges_partially_overlapping_regions():
    regions = [Region(0, 0, 2, 2), Region(1, 1, 2, 2)]
    assert list(Compositor._regions_to_spans(regions)) == [
        (0, 0, 2),
        (1, 0, 3),
        (2, 1, 3),
    ]


def test_regions_to_ranges_fully_overlapping_regions():
    regions = [Region(1, 1, 3, 3), Region(2, 2, 1, 1), Region(0, 2, 3, 1)]
    assert list(Compositor._regions_to_spans(regions)) == [
        (1, 1, 4),
        (2, 0, 4),
        (3, 1, 4),
    ]


def test_regions_to_ranges_disjoint_regions_different_lines():
    regions = [Region(0, 0, 2, 1), Region(2, 2, 2, 1)]
    assert list(Compositor._regions_to_spans(regions)) == [(0, 0, 2), (2, 2, 4)]


def test_regions_to_ranges_disjoint_regions_same_line():
    regions = [Region(0, 0, 1, 2), Region(2, 0, 1, 1)]
    assert list(Compositor._regions_to_spans(regions)) == [
        (0, 0, 1),
        (0, 2, 3),
        (1, 0, 1),
    ]


def test_regions_to_ranges_directly_adjacent_ranges_merged():
    regions = [Region(0, 0, 1, 2), Region(1, 0, 1, 2)]
    assert list(Compositor._regions_to_spans(regions)) == [
        (0, 0, 2),
        (1, 0, 2),
    ]

