import asyncio
from textual.app import App
from textual.containers import VerticalScroll
from textual.widgets import Label
from textual._compositor import CompositorUpdate, LayoutUpdate, ChopsUpdate
from textual._cells import cell_len

WIDTH, HEIGHT = 40, 12

class MyApp(App):
    CSS = """
    Label { height: 3; border: solid green; width: 100%; }
    """
    def compose(self):
        with VerticalScroll():
            for i in range(20):
                yield Label(f"Widget number {i:02d}")

def strip_chars(strip):
    chars = []
    for seg in strip:
        t = seg.text
        # expand wide chars naively: cell_len handles width but keep simple
        for ch in t:
            chars.append(ch)
    return chars

class Buffer:
    def __init__(self, w, h):
        self.w, self.h = w, h
        self.grid = [[" "] * w for _ in range(h)]
    def put(self, x, y, chars):
        if not (0 <= y < self.h):
            return
        for i, ch in enumerate(chars):
            xx = x + i
            if 0 <= xx < self.w:
                self.grid[y][xx] = ch
    def apply(self, upd):
        if isinstance(upd, LayoutUpdate):
            x = upd.region.x
            for i, strip in enumerate(upd.strips):
                self.put(x, upd.region.y + i, strip_chars(strip))
        elif isinstance(upd, ChopsUpdate):
            chops = upd.chops
            chop_ends = upd.chop_ends
            for y, x1, x2 in upd.spans:
                line = chops[y]
                ends = chop_ends[y]
                for end, (x, strip) in zip(ends, line.items()):
                    if strip is None:
                        continue
                    if x > x2 or end <= x1:
                        continue
                    chars = strip_chars(strip)
                    # place chars at columns [x, x+len), clipped to [x1, x2)
                    for i, ch in enumerate(chars):
                        col = x + i
                        if col < x1 or col >= x2:
                            continue
                        if 0 <= col < self.w and 0 <= y < self.h:
                            self.grid[y][col] = ch
    def text(self):
        return "\n".join("".join(row).rstrip() for row in self.grid)

async def main():
    app = MyApp()
    captured = []
    async with app.run_test(size=(WIDTH, HEIGHT)) as pilot:
        orig = app._display
        def patched(screen, renderable):
            if isinstance(renderable, CompositorUpdate):
                captured.append(renderable)
            return orig(screen, renderable)
        app._display = patched

        await pilot.pause()
        comp = app.screen._compositor
        buf = Buffer(WIDTH, HEIGHT)
        buf.apply(comp.render_full_update())

        for step in range(15):
            captured.clear()
            app.screen.scroll_relative(y=1, animate=False)
            await pilot.pause()
            await pilot.pause()
            for upd in captured:
                buf.apply(upd)
            gt = "\n".join(s.text for s in comp.render_strips()).rstrip()
            gt = "\n".join(l.rstrip() for l in gt.split("\n"))
            got = buf.text()
            if gt != got:
                print(f"=== MISMATCH after scroll step {step+1} (scroll_y={app.screen.scroll_offset.y}) ===")
                for ln, (a, b) in enumerate(zip(gt.split("\n"), got.split("\n"))):
                    mark = "" if a == b else "  <-- DIFF"
                    print(f"{ln:2} GT |{a}{mark}")
                    if a != b:
                        print(f"   GOT|{b}")
                break
        else:
            print("No mismatch detected across all scroll steps")

asyncio.run(main())

