import asyncio
from textual.app import App
from textual.containers import VerticalScroll
from textual.widgets import Label, Checkbox, Switch, Static
from textual._compositor import CompositorUpdate, LayoutUpdate, ChopsUpdate

WIDTH, HEIGHT = 40, 14

class MyApp(App):
    CSS = """
    .box { height: 4; border: solid green; width: 90%; margin: 1 2; }
    Checkbox { margin: 1 2; }
    Switch { margin: 1 2; }
    """
    def compose(self):
        with VerticalScroll():
            for i in range(15):
                yield Static(f"Static block {i:02d}", classes="box")
                yield Checkbox("Toggle Button")
                yield Switch()

def strip_chars(strip):
    chars = []
    for seg in strip:
        for ch in seg.text:
            chars.append(ch)
    return chars

class Buffer:
    def __init__(self, w, h):
        self.w, self.h = w, h
        self.grid = [[" "] * w for _ in range(h)]
    def put(self, x, y, chars):
        if not (0 <= y < self.h):
            return
        for i, ch in enumerate(chars):
            xx = x + i
            if 0 <= xx < self.w:
                self.grid[y][xx] = ch
    def apply(self, upd):
        if isinstance(upd, LayoutUpdate):
            x = upd.region.x
            for i, strip in enumerate(upd.strips):
                self.put(x, upd.region.y + i, strip_chars(strip))
        elif isinstance(upd, ChopsUpdate):
            chops = upd.chops
            chop_ends = upd.chop_ends
            for y, x1, x2 in upd.spans:
                line = chops[y]
                ends = chop_ends[y]
                for end, (x, strip) in zip(ends, line.items()):
                    if strip is None:
                        continue
                    if x > x2 or end <= x1:
                        continue
                    chars = strip_chars(strip)
                    for i, ch in enumerate(chars):
                        col = x + i
                        if col < x1 or col >= x2:
                            continue
                        if 0 <= col < self.w and 0 <= y < self.h:
                            self.grid[y][col] = ch
    def text(self):
        return "\n".join("".join(row).rstrip() for row in self.grid)

async def main():
    import random
    rng = random.Random(0)
    app = MyApp()
    captured = []
    async with app.run_test(size=(WIDTH, HEIGHT)) as pilot:
        orig = app._display
        def patched(screen, renderable):
            if isinstance(renderable, CompositorUpdate):
                captured.append(renderable)
            return orig(screen, renderable)
        app._display = patched

        await pilot.pause()
        comp = app.screen._compositor
        buf = Buffer(WIDTH, HEIGHT)
        buf.apply(comp.render_full_update())

        types = []
        for step in range(40):
            captured.clear()
            delta = rng.choice([1, 1, 2, -1, -1, -2, 3, -3])
            app.screen.scroll_relative(y=delta, animate=False)
            await pilot.pause()
            await pilot.pause()
            types.append("+".join(type(u).__name__[:5] for u in captured) or "none")
            for upd in captured:
                buf.apply(upd)
            gt = "\n".join(l.rstrip() for l in ("\n".join(s.text for s in comp.render_strips())).split("\n"))
            got = buf.text()
            if gt != got:
                print(f"=== MISMATCH step {step+1} delta={delta} scroll_y={app.screen.scroll_offset.y} updates={types[-1]} ===")
                for ln, (a, b) in enumerate(zip(gt.split("\n"), got.split("\n"))):
                    if a != b:
                        print(f"{ln:2} GT |{a}|")
                        print(f"   GOT|{b}|")
                return
        print("No mismatch. update types seen:", set(types))

asyncio.run(main())

